-- TeamMind Phase 1: initial business schema.
-- All IDs are generated by the application; no database-specific ID generator is required.

CREATE TABLE sys_user (
    id                  BIGINT PRIMARY KEY,
    username            VARCHAR(64) NOT NULL,
    password            VARCHAR(255) NOT NULL,
    nickname            VARCHAR(64),
    status              SMALLINT NOT NULL DEFAULT 1,
    deleted             BOOLEAN NOT NULL DEFAULT FALSE,
    created_at          TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at          TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT ck_sys_user_status CHECK (status IN (0, 1)),
    CONSTRAINT uk_sys_user_username UNIQUE (username)
);

CREATE TABLE knowledge_base (
    id                  BIGINT PRIMARY KEY,
    name                VARCHAR(128) NOT NULL,
    description         TEXT,
    owner_id            BIGINT NOT NULL,
    status              SMALLINT NOT NULL DEFAULT 1,
    deleted             BOOLEAN NOT NULL DEFAULT FALSE,
    created_at          TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at          TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_knowledge_base_owner FOREIGN KEY (owner_id) REFERENCES sys_user (id),
    CONSTRAINT ck_knowledge_base_status CHECK (status IN (0, 1))
);

CREATE TABLE knowledge_document (
    id                  BIGINT PRIMARY KEY,
    knowledge_base_id   BIGINT NOT NULL,
    document_name       VARCHAR(255) NOT NULL,
    file_type           VARCHAR(32) NOT NULL,
    file_path           VARCHAR(1024) NOT NULL,
    current_version     INTEGER NOT NULL DEFAULT 1,
    processing_status   VARCHAR(32) NOT NULL DEFAULT 'PENDING',
    failure_reason      TEXT,
    deleted             BOOLEAN NOT NULL DEFAULT FALSE,
    created_at          TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at          TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_document_knowledge_base FOREIGN KEY (knowledge_base_id) REFERENCES knowledge_base (id),
    CONSTRAINT ck_document_version CHECK (current_version > 0),
    CONSTRAINT ck_document_status CHECK (processing_status IN ('PENDING', 'PROCESSING', 'COMPLETED', 'FAILED')),
    CONSTRAINT uk_document_name_version UNIQUE (knowledge_base_id, document_name, current_version)
);

CREATE TABLE knowledge_chunk (
    id                  BIGINT PRIMARY KEY,
    document_id         BIGINT NOT NULL,
    knowledge_base_id   BIGINT NOT NULL,
    document_version    INTEGER NOT NULL,
    chunk_index         INTEGER NOT NULL,
    content             TEXT NOT NULL,
    page_number         INTEGER,
    vector_id           VARCHAR(128),
    created_at          TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_chunk_document FOREIGN KEY (document_id) REFERENCES knowledge_document (id),
    CONSTRAINT fk_chunk_knowledge_base FOREIGN KEY (knowledge_base_id) REFERENCES knowledge_base (id),
    CONSTRAINT ck_chunk_version CHECK (document_version > 0),
    CONSTRAINT ck_chunk_index CHECK (chunk_index >= 0),
    CONSTRAINT uk_chunk_document_version_index UNIQUE (document_id, document_version, chunk_index),
    CONSTRAINT uk_chunk_vector_id UNIQUE (vector_id)
);

CREATE TABLE ai_conversation (
    id                  BIGINT PRIMARY KEY,
    conversation_id     VARCHAR(64) NOT NULL,
    user_id             BIGINT NOT NULL,
    title               VARCHAR(255),
    deleted             BOOLEAN NOT NULL DEFAULT FALSE,
    created_at          TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at          TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_conversation_user FOREIGN KEY (user_id) REFERENCES sys_user (id),
    CONSTRAINT uk_conversation_identifier UNIQUE (conversation_id)
);

CREATE TABLE ai_memory (
    id                  BIGINT PRIMARY KEY,
    user_id             BIGINT NOT NULL,
    memory_type         VARCHAR(64) NOT NULL,
    content             TEXT NOT NULL,
    source_conversation_id VARCHAR(64),
    version             INTEGER NOT NULL DEFAULT 1,
    status              VARCHAR(32) NOT NULL DEFAULT 'ACTIVE',
    created_at          TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at          TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_memory_user FOREIGN KEY (user_id) REFERENCES sys_user (id),
    CONSTRAINT fk_memory_conversation FOREIGN KEY (source_conversation_id) REFERENCES ai_conversation (conversation_id),
    CONSTRAINT ck_memory_version CHECK (version > 0),
    CONSTRAINT ck_memory_status CHECK (status IN ('DRAFT', 'ACTIVE', 'INVALID'))
);

CREATE TABLE ai_trace (
    id                  BIGINT PRIMARY KEY,
    trace_id            VARCHAR(64) NOT NULL,
    user_id             BIGINT,
    conversation_id     VARCHAR(64),
    status              VARCHAR(32) NOT NULL,
    total_duration      BIGINT,
    total_tokens        BIGINT,
    created_at          TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_trace_user FOREIGN KEY (user_id) REFERENCES sys_user (id),
    CONSTRAINT fk_trace_conversation FOREIGN KEY (conversation_id) REFERENCES ai_conversation (conversation_id),
    CONSTRAINT ck_trace_status CHECK (status IN ('RUNNING', 'SUCCESS', 'FAILED', 'TIMEOUT')),
    CONSTRAINT ck_trace_duration CHECK (total_duration IS NULL OR total_duration >= 0),
    CONSTRAINT ck_trace_tokens CHECK (total_tokens IS NULL OR total_tokens >= 0),
    CONSTRAINT uk_trace_identifier UNIQUE (trace_id)
);

CREATE TABLE ai_trace_span (
    id                  BIGINT PRIMARY KEY,
    trace_id            VARCHAR(64) NOT NULL,
    span_id             VARCHAR(64) NOT NULL,
    parent_span_id      VARCHAR(64),
    span_type           VARCHAR(64) NOT NULL,
    status              VARCHAR(32) NOT NULL,
    duration            BIGINT,
    error_message       TEXT,
    input_summary       TEXT,
    output_summary      TEXT,
    created_at          TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_span_trace FOREIGN KEY (trace_id) REFERENCES ai_trace (trace_id) ON DELETE CASCADE,
    CONSTRAINT ck_span_status CHECK (status IN ('RUNNING', 'SUCCESS', 'FAILED', 'TIMEOUT')),
    CONSTRAINT ck_span_duration CHECK (duration IS NULL OR duration >= 0),
    CONSTRAINT ck_span_parent CHECK (parent_span_id IS NULL OR parent_span_id <> span_id),
    CONSTRAINT uk_span_identifier UNIQUE (trace_id, span_id)
);

CREATE TABLE ai_evidence (
    id                  BIGINT PRIMARY KEY,
    trace_id            VARCHAR(64) NOT NULL,
    document_id         BIGINT NOT NULL,
    chunk_id            BIGINT NOT NULL,
    document_version    INTEGER NOT NULL,
    retrieval_type      VARCHAR(32) NOT NULL,
    retrieval_score     DECIMAL(18, 10),
    rerank_score        DECIMAL(18, 10),
    created_at          TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_evidence_trace FOREIGN KEY (trace_id) REFERENCES ai_trace (trace_id) ON DELETE CASCADE,
    CONSTRAINT fk_evidence_document FOREIGN KEY (document_id) REFERENCES knowledge_document (id),
    CONSTRAINT fk_evidence_chunk FOREIGN KEY (chunk_id) REFERENCES knowledge_chunk (id),
    CONSTRAINT ck_evidence_version CHECK (document_version > 0),
    CONSTRAINT ck_evidence_retrieval_type CHECK (retrieval_type IN ('DENSE', 'BM25', 'HYBRID')),
    CONSTRAINT uk_evidence_trace_chunk UNIQUE (trace_id, chunk_id)
);

CREATE INDEX idx_knowledge_base_owner ON knowledge_base (owner_id) WHERE NOT deleted;
CREATE INDEX idx_document_base_status ON knowledge_document (knowledge_base_id, processing_status) WHERE NOT deleted;
CREATE INDEX idx_chunk_document_version ON knowledge_chunk (document_id, document_version);
CREATE INDEX idx_chunk_base_version ON knowledge_chunk (knowledge_base_id, document_version);
CREATE INDEX idx_conversation_user_created ON ai_conversation (user_id, created_at DESC) WHERE NOT deleted;
CREATE INDEX idx_memory_user_status ON ai_memory (user_id, status);
CREATE INDEX idx_trace_conversation ON ai_trace (conversation_id);
CREATE INDEX idx_trace_created ON ai_trace (created_at DESC);
CREATE INDEX idx_span_trace_parent ON ai_trace_span (trace_id, parent_span_id);
CREATE INDEX idx_evidence_trace ON ai_evidence (trace_id);
